import{_ as a,c as t,o,a3 as s}from"./chunks/framework.C5U8cnJv.js";const i="/xhh-blog/assets/image-12.Cy8_6tvv.png",l="/xhh-blog/assets/image-11.7ubJJn-Q.png",q=JSON.parse('{"title":"Github Copilot","description":"","frontmatter":{},"headers":[],"relativePath":"ai/githubcopilot.md","filePath":"ai/githubcopilot.md"}'),e={name:"ai/githubcopilot.md"},p=s(`<h1 id="github-copilot" tabindex="-1">Github Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;Github Copilot&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>GitHub Copilot 是 GitHub 与 OpenAI 合作推出的编程辅助工具。它基于大规模语言模型，为你在编辑器中提供自动补全、代码片段建议、整段实现和注释生成等能力，帮助你更快地编写代码、探索实现思路和生成文档示例。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>以 VS Code 为例</p><ol><li>打开 VS Code。</li><li>在扩展市场（Extensions）中搜索 “GitHub Copilot”，或直接搜索 <code>Copilot</code> 并选择由 GitHub 发布的插件安装。</li><li>安装完成后，你需要使用 GitHub 账号登录并完成授权（安装后通常会弹出登录引导窗口，按提示完成）。</li></ol><h2 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h2><p>1.Ctrl+Alt+I‌ (Control+Command+I) 打开聊天界面；</p><p>2.选中行 =&gt; Add Selection to Chat;</p><p>3.在输入代码或注释时，Copilot 会以灰色 &quot;ghost text&quot; 形式给出建议，按 Tab 接受建议，按 ‌Esc‌ 忽略；</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>项目级：</p><ul><li>.github/skills/</li><li>.agents/skills/</li><li>.claude/skills/</li></ul><p>个人全局skills(所有项目生效)</p><ul><li>~/.copilot/skills/</li><li>~/.agents/skills/</li><li>~/.claude/skills/</li></ul><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h2><p>连接 Figma MCP</p><h3 id="第一种-项目工作区配置" tabindex="-1">第一种：项目工作区配置 <a class="header-anchor" href="#第一种-项目工作区配置" aria-label="Permalink to &quot;第一种：项目工作区配置&quot;">​</a></h3><p>项目根目录 .vscode 文件夹下 新建 mcp.json:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;inputs&quot;: [],</span></span>
<span class="line"><span>  &quot;servers&quot;: {</span></span>
<span class="line"><span>    &quot;figma&quot;: {</span></span>
<span class="line"><span>      &quot;type&quot;: &quot;http&quot;,</span></span>
<span class="line"><span>      &quot;url&quot;: &quot;https://mcp.figma.com/mcp&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存后，在 mcp.json 文件中点击 figma 上方的 Start，连接 Figma MCP</p><h3 id="第二种-copilot-设置里配置" tabindex="-1">第二种：Copilot 设置里配置 <a class="header-anchor" href="#第二种-copilot-设置里配置" aria-label="Permalink to &quot;第二种：Copilot 设置里配置&quot;">​</a></h3><p>Copilot 设置里找到 MCP Servers，安装 Figma MCP Server <img src="`+i+'" alt="alt text"></p><p>启动服务</p><p><img src="'+l+'" alt="alt text"></p><p>同意授权即可。</p><h3 id="第三种-用户全局配置-本机所有项目生效" tabindex="-1">第三种：用户全局配置（本机所有项目生效） <a class="header-anchor" href="#第三种-用户全局配置-本机所有项目生效" aria-label="Permalink to &quot;第三种：用户全局配置（本机所有项目生效）&quot;">​</a></h3><p>1.打开命令面板，执行 <code>MCP: Add Server</code></p><p>2.选择<code>http</code>类型，填入 Figma MCP 地址 <code>https://mcp.figma.com/mcp</code></p><p>3.选择保存为<strong>User 设置（全局）</strong>，启动并完成授权。</p><h2 id="参考文档" tabindex="-1">参考文档 <a class="header-anchor" href="#参考文档" aria-label="Permalink to &quot;参考文档&quot;">​</a></h2><p><a href="https://docs.github.com/zh/copilot" target="_blank" rel="noreferrer">https://docs.github.com/zh/copilot</a></p>',32),n=[p];function c(r,h,d,u,m,b){return o(),t("div",null,n)}const _=a(e,[["render",c]]);export{q as __pageData,_ as default};
